navage.com.apply:
try {
	const field = document.querySelector('input#couponcode, input[name=redeemableCode]')
	field.dispatchEvent(new Event('input', { bubbles: true }));
	field.dispatchEvent(new Event('keyup'));
	field.dispatchEvent(new Event('blur'));
	field.dispatchEvent(new Event('focus'));
	document.querySelector('.coupon-form [type=submit], #applyRedeemableButton').click();
} catch(e) {}

